            for k,v in children: body.append(emit(k,v,depth+2))
            return f'{indent}<{name}{attrtext}>\n'+'\n'.join(body)+f'\n{indent}</{name}>'
        return f'{indent}<{name}>{_xml_escape(_cell(val))}</{name}>'
    return emit(str(tag),contents,0)+'\n'


