"""Small INI adapter for the Dasel CLI compatibility layer."""

from __future__ import annotations


def parse_ini(text: str) -> dict:
    """Parse INI into nested dictionaries, keeping all values as strings."""
    result: dict = {}
    section: dict = result
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith((";", "#")):
            continue
        if line.startswith("[") and line.endswith("]"):
            name = line[1:-1].strip()
            section = result.setdefault(name, {})
            if not isinstance(section, dict):
                section = {}
                result[name] = section
            continue
        # Inline comments are data in INI values, so only whole-line comments
        # are stripped.
        if "=" in line:
            key, value = line.split("=", 1)
        elif ":" in line:
            key, value = line.split(":", 1)
        else:
            key, value = line, ""
        section[key.strip()] = value.strip()
    return result


def dump_ini(value) -> str:
    """Serialize a map using the simple section/key syntax accepted by Dasel."""
    if not isinstance(value, dict):
        raise ValueError("ini can only represent map values")
    lines: list[str] = []
    roots = [(k, v) for k, v in value.items() if not isinstance(v, dict)]
    if roots:
        lines.extend(f"{k} = {_scalar(v)}" for k, v in roots)
    def emit(section: dict, path: list[str]) -> None:
        if lines:
            lines.append("")
        lines.append("[" + " ".join(path) + "]")
        for key, item in section.items():
            if not isinstance(item, dict):
                lines.append(f"{key} = {_scalar(item)}")
        for key, item in section.items():
            if isinstance(item, dict):
                emit(item, path + [str(key)])
    for key, item in value.items():
        if isinstance(item, dict):
            emit(item, [str(key)])
    return "\n".join(lines) + ("\n" if lines else "")


